<?php\n\nnamespace App\Http\Controllers\Checkout;\n\nuse App\Domain\Cart\Services\CartService;\nuse App\Http\Controllers\Controller;\nuse Illuminate\Http\Request;\n\nclass CheckoutController extends Controller\n{\n    public function __construct(protected CartService ) {}\n\n    public function index()\n    {\n        \ = \->cart->getCurrentCart();\n        if (\->items->isEmpty()) {\n            return redirect()->route('cart.index')->with('error', 'Cosul este gol.');\n        }\n        \ = \->cart->subtotal(\);\n        return view('checkout.index', compact('cart', 'subtotal'));\n    }\n\n    public function store(Request \)\n    {\n        \ = \->validate([\n            'email' => ['required', 'email'],\n            'first_name' => ['required', 'string', 'max:255'],\n            'last_name' => ['required', 'string', 'max:255'],\n            'phone' => ['required', 'string', 'max:50'],\n            'address_line1' => ['required', 'string', 'max:255'],\n            'city' => ['required', 'string', 'max:255'],\n            'postal_code' => ['required', 'string', 'max:20'],\n            'country' => ['required', 'string', 'max:2'],\n            'payment_method' => ['required', 'in:cod,card'],\n        ]);\n\n        \ = \->cart->getCurrentCart();\n        return redirect()->route('checkout.success')->with('order_pending', true);\n    }\n\n    public function success()\n    {\n        return view('checkout.success');\n    }\n}\n